/* @autogenerated */
import { TenantRepository } from 'app/features/identity/tenant/repository/tenant-repository.service';
import { OauthClientRepository } from 'app/features/access/oauth-client/repository/oauth-client-repository.service';
import { normalizeHeader } from 'app/shared/toolkit/entity-import/column-match';
import { take, map } from 'rxjs';
import { BaseImportAction } from 'app/shared/toolkit/action/base-import-action';
import { ImportDefinition } from 'app/shared/toolkit/entity-import/entity-import.model';
import { Component, inject } from '@angular/core';
import { OauthClient } from 'app/features/access/oauth-client/model/oauth-client.model';
import {
  OAUTH_CLIENT_EXCEL_COLUMNS,
  OAUTH_CLIENT_EXCEL_SENSITIVE,
} from 'app/features/access/oauth-client/model/oauth-client-excel-columns';

/** Candidatos que pide cada búsqueda: el filtro puede no ser exacto y se comprueba aquí. */
const LOOKUP_LIMIT = 50;

@Component({
  selector: 'oauth-client-view-import-action',
  standalone: false,
  templateUrl: './oauth-client-view-import-action.component.html',
})
export class OauthClientViewImportActionComponent extends BaseImportAction<OauthClient> {
  protected readonly scope = 'access/oauth-client';
  protected readonly repository = inject(OauthClientRepository);
  private readonly tenantRepository = inject(TenantRepository);

  readonly definition: ImportDefinition<OauthClient> = {
    storageKey: 'access.oauth-client',
    scope: this.scope,
    // Clave natural (índice único del modelo): una fila con los mismos valores actualiza el elemento
    keys: ['tenant', 'code'],
    columns: OAUTH_CLIENT_EXCEL_COLUMNS,
    sensitive: OAUTH_CLIENT_EXCEL_SENSITIVE,
    // Campos que el backend solo cambia con sus acciones: se aplican tras crear o actualizar
    actions: {
      enabled: [
        { name: 'enable', value: true, run: (item) => this.repository.enable(item.uid) },
        { name: 'disable', value: false, run: (item) => this.repository.disable(item.uid) },
      ],
    },
    references: {
      tenant: {
        resolve: (text) =>
          this.tenantRepository.values({ search: text, limit: LOOKUP_LIMIT }).pipe(
            take(1),
            map((found) => {
              const wanted = normalizeHeader(text);
              const one = found.find(
                (candidate) => candidate.uid === text || normalizeHeader(candidate.name) === wanted,
              );
              return one ? { $ref: one.uid } : null;
            }),
          ),
      },
    },
    defaults: () => ({
      tokenEndpointAuthMethod: 'client-secret-basic',
      tokenEndpointAuthSigningAlg: 'RS256',
      dpopBoundAccessTokens: false,
      idTokenSignedResponseAlg: 'rs256',
      tlsClientCertificateBoundAccessTokens: false,
      subjectType: 'public',
      grantTypesJson: '["authorization_code","refresh_token"]',
      introspectionAllowed: false,
      requirePushedAuthorizationRequests: false,
      requirePkce: false,
      enabled: false,
      clientCredentialsTokenTtlSeconds: 3600,
    }),
    display: (values) => String(values.code ?? ''),
    target: {
      acl: () => this.repository.checkAcl(),
      find: (values) =>
        this.repository
          .values({
            tenant: values.tenant?.$ref ? [values.tenant.$ref] : undefined,
            code: values.code,
            limit: LOOKUP_LIMIT,
          })
          .pipe(
            take(1),
            map((found) =>
              found.filter(
                (item) =>
                  (!values.tenant?.$ref || item.tenant?.$ref === values.tenant.$ref) && item.code === values.code,
              ),
            ),
          ),
      add: (item) => this.repository.add(item),
      update: (item) => this.repository.update(item),
    },
  };
}
